"""Author / creator / last modified by: Chunhao Guo. Assemble only saved results."""
from pathlib import Path
import csv, json, math, hashlib, html, re
ROOT=Path('/LOCAL_PROJECT_ROOT')
OUT=ROOT/'84_JCO_PO_Upgrade_20261113/05_analysis/B2_independent_cohorts'
R=OUT/'results'
def read(n):return list(csv.DictReader((R/n).open()))
def num(v):
    try:return float(v)
    except (ValueError,TypeError):return math.nan
def f(v,d=1):return f'{num(v):.{d}f}' if math.isfinite(num(v)) else 'unavailable'
def ci(a,b,d=1):return f'{f(a,d)}–{f(b,d)}' if math.isfinite(num(a)) else 'not estimable'
def table(headers,rows):
    return '\n'.join(['| '+' | '.join(headers)+' |','|'+'|'.join(['---']*len(headers))+'|']+['| '+' | '.join(map(str,row))+' |' for row in rows])
def src(n):return f'`results/{n}`'
def unit(co,n):return f'{n} tumour regions / 79 patients' if co=='TRACERx' else f'{n} '+('cases' if co=='CPTAC' else 'patients')
cohorts=['CM025','TRACERx','TCGA','CPTAC'];primary=[];non=[]
resources=[]
for name in ['00_extract_cm025.log','01_prepare_final.log','02_CM025_nominated.log','02_TRACERx_nominated.log','02_TCGA_nominated.log','02_CPTAC_nominated.log','03_clinical_nominated.log','04_validate_nominated.log']:
    s=(OUT/'logs'/name).read_text();rss=re.search(r'(\d+)\s+maximum resident set size',s);foot=re.search(r'(\d+)\s+peak memory footprint',s)
